import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    先执行PyTorch的Conv2d，再用自定义AscendC算子完成：沿通道最小值 + Tanh + Tanh
    """
    def __init__(self, in_channels, out_channels, kernel_size):
